/* Brain Atlas Mode 1 v0.5B — opacity + explicitly schematic pathway continuity.
   Built from the ORIGINAL medulla oblongata mesh cross-sections, not the
   whole-brain centroid. Cervical levels, cross-sectional internal regions,
   and inferior curvature remain schematic (educational, not diagnostic).
   CC BY-SA 4.0 derivative model; original Brain Project attribution retained.
*/
(function(){
'use strict';
// Retain the recovered real missing hemimedulla from the latest patch.
const MED_POS='';
const MED_IDX='';
function dec(s){const b=atob(s),v=new Uint8Array(b.length);for(let i=0;i<b.length;i++)v[i]=b.charCodeAt(i);return v.buffer;}
function geo(T,pp,ii){const g=new T.BufferGeometry();g.setAttribute('position',new T.BufferAttribute(new Float32Array(dec(pp)),3));g.setIndex(new T.BufferAttribute(new Uint16Array(dec(ii)),1));g.computeVertexNormals();g.computeBoundingBox();g.computeBoundingSphere();return g;}

function sampleSection(T,mesh,y){
  const p=mesh.geometry.getAttribute('position'),ind=mesh.geometry.getIndex();
  if(!p)return null;
  const segments=[];
  const faceCount=ind?ind.count:p.count;
  const verts=[new T.Vector3(),new T.Vector3(),new T.Vector3()];
  for(let q=0;q+2<faceCount;q+=3){
    for(let k=0;k<3;k++)verts[k].fromBufferAttribute(p,ind?ind.getX(q+k):q+k);
    const hits=[];
    for(const [a,b] of [[0,1],[1,2],[2,0]]){
      const u=verts[a],v=verts[b],dy=v.y-u.y;
      if(Math.abs(dy)<1e-10)continue;
      const t=(y-u.y)/dy;
      if(t>=0&&t<=1)hits.push([u.x+t*(v.x-u.x),u.z+t*(v.z-u.z)]);
    }
    if(hits.length>=2)segments.push(...hits.slice(0,2));
  }
  if(segments.length<12)return null;
  const xs=segments.map(v=>v[0]).sort((a,b)=>a-b),zs=segments.map(v=>v[1]).sort((a,b)=>a-b);
  const pct=(a,v)=>a[Math.round((a.length-1)*v)];
  // Trim extreme one-vertex spikes to obtain a robust outer cross-section.
  return {y,minX:pct(xs,.01),maxX:pct(xs,.99),
    minZ:pct(zs,.01),maxZ:pct(zs,.99),n:segments.length};
}
function build(T,meshes,coreHeight){
  const mesh=meshes&&meshes.find(m=>m?.isMesh&&m.geometry?.getAttribute('position'));
  if(!mesh)return null;
  if(!mesh.geometry.boundingBox)mesh.geometry.computeBoundingBox();
  const bounds=mesh.geometry.boundingBox.clone();
  const medHeight=bounds.max.y-bounds.min.y;
  // Two actual medulla sections determine junction center and inferior tangent.
  const a=sampleSection(T,mesh,bounds.min.y+Math.min(medHeight*.064,.0025));
  const b=sampleSection(T,mesh,bounds.min.y+Math.min(medHeight*.25,.010));
  if(!a||!b)return null;
  const midlineX=0; // unpaired left hemimedulla; 0 is its verified medial edge
  const z0=(a.minZ+a.maxZ)/2;
  const z1=(b.minZ+b.maxZ)/2;
  const tangent=Math.max(-.7,Math.min(.7,(z1-z0)/(b.y-a.y)));
  const topY=a.y;
  const length=coreHeight*.78;
  const rx0=Math.max(.0035,a.maxX-midlineX),rz0=Math.max(.0035,(a.maxZ-a.minZ)/2);
  const group=new T.Group();group.name='頸髄 — cervical cord (schematic, cross-section anchored)';
  group.userData={type:'schematic',source:'Brain Project medulla mesh lower cross-section',anatomicalRange:'upper cervical through C5–T1 spinal segments'};
  // Tangent-matching junction, gently approaching a near-vertical cord below.
  const yAt=t=>topY-length*t;
  const zAt=t=>z0-tangent*.020*(1-Math.exp(-(length*t)/.020))-.009*t*t;
  const radiusAt=t=>{
    const cervicalEnlargement=1+.22*Math.exp(-Math.pow((t-.69)/.21,2));
    return (1-.12*Math.min(1,t/.20))*cervicalEnlargement;
  };
  const rzAt=t=>rz0*radiusAt(t),rxAt=t=>rx0*radiusAt(t);
  const sections=112,radial=48,positions=[],ids=[];
  for(let j=0;j<=sections;j++){
    const t=j/sections;
    for(let k=0;k<=radial;k++){
      const angle=k/radial*Math.PI*2;
      positions.push(midlineX+rxAt(t)*Math.cos(angle),yAt(t),zAt(t)+rzAt(t)*Math.sin(angle));
    }
  }
  for(let j=0;j<sections;j++)for(let k=0;k<radial;k++){
    const a=j*(radial+1)+k,b=(j+1)*(radial+1)+k;
    ids.push(a,b,a+1,b,b+1,a+1);
  }
  const bottomCenter=positions.length/3;
  positions.push(midlineX,yAt(1),zAt(1));
  for(let k=0;k<radial;k++)ids.push(bottomCenter,sections*(radial+1)+k,sections*(radial+1)+k+1);
  const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setIndex(ids);geo.computeVertexNormals();
  const cord=new T.Mesh(geo,new T.MeshStandardMaterial({color:0xD7DCE7,roughness:.83,metalness:0,side:T.DoubleSide,transparent:true,opacity:1,depthWrite:true}));
  cord.name='頸髄（模式的外形）';group.add(cord);
  // Segment bands are schematic labels, not precise intervertebral levels.
  const bands=[['C5',.52],['C6',.62],['C7',.72],['C8',.82],['T1',.92]];
  const bandMat=new T.MeshBasicMaterial({color:0x86C6D8,transparent:true,opacity:.6,depthWrite:false});
  for(const [name,t]of bands){
    const pts=[];for(let k=0;k<=64;k++){const angle=k/64*Math.PI*2;pts.push(new T.Vector3(midlineX+rxAt(t)*1.009*Math.cos(angle),yAt(t),zAt(t)+rzAt(t)*1.009*Math.sin(angle)));}
    const ring=new T.Mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts),64,Math.max(rx0*.04,.0001),4,false),bandMat.clone());ring.name=`脊髄分節${name}（模式表示）`;group.add(ring);
  }
  // The specimen and the cervical extension share the same cortex-opacity
  // control. Tract overlays do NOT fade, so their position remains intelligible.
  const tissueMeshes=[cord,...group.children.filter(o=>o.isMesh && o!==cord)];
  const originalOpacities=tissueMeshes.map(m=>m.material.opacity);
  function setOpacity(alpha){
    const a=Math.max(0,Math.min(1,Number(alpha)||0));
    tissueMeshes.forEach((m,i)=>{
      m.material.transparent=true;
      m.material.opacity=a*originalOpacities[i];
      m.material.depthWrite=m.material.opacity>=.98;
      m.material.needsUpdate=false;
    });
  }
  // LEGACY PATHWAY BUILDER DISABLED in v0.6A.6: this block is not called.
  // These two continuations are intentionally anatomical SCHEMATICS, not traced
  // human fiber tracts. Existing GLB geometry is retained in its own meshes.
  const pathways=new T.Group();pathways.name='模式的な頸髄神経路（非実測）';group.add(pathways);
  const routeMeshes={};
  function findInferiorTerminal(meshes){
    const m=meshes?.find(o=>o?.isMesh&&o.geometry?.getAttribute('position'));
    if(!m)return null;
    const attr=m.geometry.getAttribute('position');
    m.updateWorldMatrix(true,false);group.updateWorldMatrix(true,false);
    const toLocal=group.matrixWorld.clone().invert().multiply(m.matrixWorld);
    const p=new T.Vector3(),bottom=new T.Vector3();let lo=Infinity,hi=-Infinity;
    // Two-pass inferior vertex sampling; avoid the extreme single-vertex outlier.
    for(let k=0;k<attr.count;k++){p.fromBufferAttribute(attr,k).applyMatrix4(toLocal);lo=Math.min(lo,p.y);hi=Math.max(hi,p.y);}
    const cutoff=lo+Math.max((hi-lo)*.018,0.0005);
    let n=0;bottom.set(0,0,0);
    for(let k=0;k<attr.count;k++){
      p.fromBufferAttribute(attr,k).applyMatrix4(toLocal);
      if(p.y<=cutoff){bottom.add(p);n++;}
    }
    if(!n)return null;return bottom.multiplyScalar(1/n);
  }
  function addPath(label,side,points,color,description){
    const path=new T.CatmullRomCurve3(points);
    const radius=Math.max(.00045,Math.min(rx0*.13,.0013));
    const geom=new T.TubeGeometry(path,100,radius,7,false);
    const mat=new T.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.19,roughness:.45});
    const obj=new T.Mesh(geom,mat);
    obj.name=description+'（教育用模式経路）';
    obj.userData={type:'schematic-tract',label,side,notDiagnostic:true,lowerXSign:Math.sign(points[points.length-1].x)};
    obj.visible=false;pathways.add(obj);routeMeshes[label+'|'+side]=obj;
  }
  function buildPathways(meshById,nodes){
    for(const side of ['left','right']){
      const routeEnd=label=>{
        const node=nodes.find(n=>n.label===label&&n.side===side);
        return node?findInferiorTerminal(meshById.get(node.id)):null;
      };
      const lowerCST=routeEnd('Corticospinal tract');
      if(lowerCST){
        // Start at the observed lower end of the loaded GLB tract, then cross
        // in the caudal medulla before descending CONTRALATERALLY in the cord.
        const sign=Math.sign(lowerCST.x)|| (side==='left'?1:-1);
        const at=t=>new T.Vector3(-sign*rxAt(t)*.57,yAt(t),zAt(t)-rzAt(t)*.15);
        const midY=Math.min(lowerCST.y-.0008,topY+.005);
        addPath('Corticospinal tract',side,[lowerCST,
          new T.Vector3(sign*rx0*.29,midY,z0+rz0*.20),
          new T.Vector3(sign*rx0*.18,topY+.001,z0+rz0*.16),
          new T.Vector3(0,yAt(.06),zAt(.06)+rzAt(.06)*.10),
          at(.18),at(.48),at(.83),at(.99)],0x00B6FF,
          '錐体交叉から対側外側皮質脊髄路への延長');
      }
      const lowerML=routeEnd('Medial lemniscus');
      if(lowerML){
        const sign=Math.sign(lowerML.x)|| (side==='left'?1:-1);
        const at=t=>new T.Vector3(-sign*rxAt(t)*.18,yAt(t),zAt(t)-rzAt(t)*.68);
        addPath('Medial lemniscus',side,[lowerML,
          new T.Vector3(sign*rx0*.12,topY+.003,z0+rz0*.10),
          new T.Vector3(0,yAt(.06),zAt(.06)-rzAt(.06)*.10),
          at(.19),at(.50),at(.84),at(.99)],0xAA58FF,
          '後索から延髄の感覚交叉・内側毛帯への接続');
      }
    }
  }
  let selectedPathways=[];
  function setPathways(labels,hemisphere){
    selectedPathways=labels||[];
    Object.values(routeMeshes).forEach(obj=>{
      const included=selectedPathways.includes(obj.userData.label);
      obj.visible=included && (hemisphere==='both'||hemisphere===obj.userData.side);
    });
  }
  // Marker coordinates are tied to the physical tube positions, not to a
  // separate hand-drawn axial image. They are teaching schematic locations.
  function getPathwaySectionMarkers(part,hemisphere){
    const t=part.t,items=[];
    for(const side of ['left','right']){
      if(hemisphere!=='both'&&hemisphere!==side)continue;
      const cst=routeMeshes['Corticospinal tract|'+side];
      const ml=routeMeshes['Medial lemniscus|'+side];
      if(cst?.visible && t>=.2){
        items.push({label:'外側皮質脊髄路（模式）',en:'Lateral corticospinal tract',color:'#00B6FF',
          u:cst.userData.lowerXSign*.57,v:-.15});
      }
      if(ml?.visible && t>=.2){
        items.push({label:'後索（模式）',en:'Dorsal columns',color:'#AA58FF',
          u:ml.userData.lowerXSign*.18,v:-.68});
      }
    }
    return items;
  }
  const getSectionAt=y=>{
    if(y>topY+.0001||y<yAt(1)-.0001)return null;
    const t=Math.max(0,Math.min(1,(topY-y)/length));
    return {y,t,x:midlineX,z:zAt(t),rx:rxAt(t),rz:rzAt(t),
      outline:Array.from({length:128},(_,i)=>{
        const phi=i*Math.PI*2/128;
        return [midlineX+rxAt(t)*Math.cos(phi),zAt(t)+rzAt(t)*Math.sin(phi)];
      }),
      level:t<.48?'上位頸髄':(bands.reduce((best,item)=>Math.abs(item[1]-t)<Math.abs(best[1]-t)?item:best,bands[0])[0]+'分節付近')};
  };
  console.info('[Brain Atlas v0.5A.1] Junction medulla slice',{
    y:topY,zCenter:z0,secondZ:z1,axisSlope:tangent,
    width:rx0*2,depth:rz0*2,wholeMedullaZ:(bounds.min.z+bounds.max.z)/2});
  // Restore the real right hemimedulla while reverting ONLY the failed spinal exterior.
  // This is a child of the original left hemimedulla and shares its material.
  let medullaComplement=null;
  try {
    medullaComplement=new T.Mesh(geo(T,MED_POS,MED_IDX),mesh.material);
    medullaComplement.name='延髄欠損側（BodyParts3D 実メッシュ）';
    medullaComplement.frustumCulled=false;
    medullaComplement.userData={source:'BodyParts3D',repairedMissingHemimedulla:true};
    mesh.add(medullaComplement);
  }catch(err){
    console.error('[Brain Atlas rollback] missing medulla complement unavailable',err);
  }
  return {group,topY,bottomY:yAt(1),sourceBounds:bounds,
    segments:bands,anchor:{y:topY,z:z0,upperZ:z1,tangent},getSectionAt,
    setOpacity,buildPathways(){},setPathways(){},getPathwaySectionMarkers(){return [];},
    getTractCrossingsAtY(){return [];},onReady(cb){if(typeof cb==='function')cb();},
    medullaComplement,ready:true,error:null};
}
window.BrainCervical={build};
})();
